mapper.select:
SELECT pt.transaction_id, pt.account_id, pt.product_id, fp.product_name, pt.transaction_type, pt.quantity, pt.nav, pt.amount, pt.transaction_at FROM product_transaction pt JOIN financial_product fp ON pt.product_id = fp.product_id
pt.account_id = #{accountId}
AND pt.transaction_at >= #{from}
AND pt.transaction_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
ORDER BY pt.transaction_at DESC
